-- Native HRIS tool classification — deterministic, rules-based seed/delta.
-- Connectors: deel, factorial, hibob, personio, ukg_pro, ukg_ready, dayforce, adp_run, adp_workforce_now.
-- Emits every RUNTIME tool (mergeTools(hand-authored <VENDOR>_FUNCTIONS, generated))
-- for these connectors that is NOT already seeded (by name+hash) in 276_native_hris_tool_classification.sql
-- — i.e. their full first-class + passthrough surface, with hashes computed from
-- the RUNTIME descriptions so the seed is a tool_classification_cache HIT (no
-- runtime LLM call). Rules: read -> []; write/destructive -> ['dataChanges']
-- (+ 'financialActions' on pay/comp/tax/bank paths); {vendor}_native_request
-- passthrough -> always-HITL ['dataChanges','financialActions','customerCommunication']
-- (can call any endpoint). Regenerate: HRIS_CLASSIFICATION_CONNECTORS=<csv>
-- SEED_MIGRATION_PATH=<seed> scripts/audit-hris-classification.ts <out.sql>.

ON CONFLICT (tool_name, COALESCE(tenant_id, '__global__')) DO UPDATE
  SET categories = EXCLUDED.categories,
      integration_type = EXCLUDED.integration_type,
      tool_description_hash = EXCLUDED.tool_description_hash,
      reviewed_by = EXCLUDED.reviewed_by,
      classified_at = NOW();

